      <v-divider />

      <!-- Action Buttons Footer -->
      <v-card-actions class="pa-4 px-5">
        <!-- Mode: Config Buttons -->
        <template v-if="dialogMode === 'config'">
          <v-btn data-testid="backup-restore-cancel" variant="text" :disabled="isRestoring" @click="hide">
            {{ t('shared.cancel') }}
          </v-btn>
          <v-spacer />
          <v-btn
            v-if="manifest"
